}
function teamDay(team: number, index: number, weekend: boolean): DailyRow {
    const completed = Math.round((19 + 5 * team + index * 0.035 + 4 * Math.sin(0.48 * index + 1.7 * team) + 3 * Math.cos(0.19 * index)) *
        (weekend ? 0.28 : 1));
