        completed,
        hours: Math.round(completed * (1.4 + team * 0.15) * 10) / 10,
        onTime: 88 + team * 1.5 + index * 0.025 + (2 * Math.sin(index * 0.48 + team * 1.7) + 1.5 * Math.cos(index * 0.19)),
        active: weekend ? Math.round(staff * 0.4) : staff,
    };
}
function dailyRow(team: TeamId, n: number): DailyRow | null {
    const index = n - MIN_N;
    if (index < 0)
        return null;
    const day = fromDayNumber(n);
    const wd = weekday(day);
    const weekend = wd === 0 || wd === 6;
    if (team !== "all")
        return teamDay(MEMBER_TEAMS.indexOf(team), index, weekend);
    const rows = MEMBER_TEAMS.map((_, t) => teamDay(t, index, weekend));
    const completed = rows.reduce((sum, r) => sum + r.completed, 0);
    return {
        completed,
        hours: rows.reduce((sum, r) => sum + r.hours, 0),
        onTime: completed ? rows.reduce((sum, r) => sum + r.onTime * r.completed, 0) / completed : 0,
        active: rows.reduce((sum, r) => sum + r.active, 0),
